#!/usr/bin/env python3
"""Comparison-only object views must never replace native linker inputs."""
import json
import os
from pathlib import Path
import re
import sys
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
from tools.project import Object, ProjectConfig, generate_build_ninja, generate_objdiff_config, _listdir_cache


class SourceComparisonConfigTests(unittest.TestCase):
    def setUp(self):
        directory = tempfile.TemporaryDirectory()
        previous = Path.cwd()
        os.chdir(directory.name)
        self.addCleanup(directory.cleanup)
        self.addCleanup(os.chdir, previous)
        _listdir_cache.clear()
        self.addCleanup(_listdir_cache.clear)
        self.config = ProjectConfig()
        for key, value in {
            'version': 'GC6E01', 'config_path': Path('config.yml'),
            'check_sha_path': Path('build.sha1'), 'linker_version': 'GC/1.2.5n',
            'ldflags': [], 'libs': [], 'asm_dir': None, 'dtk_tag': 'v1.8.3',
            'objdiff_tag': 'v3.6.1', 'compilers_tag': 'test', 'binutils_tag': 'test',
            'sjiswrap_tag': 'v1.2.2', 'wibo_tag': '1.0.3',
        }.items():
            setattr(self.config, key, value)
        source = Path('src/sound.c')
        source.parent.mkdir()
        source.write_text('const char *names[] = {"sample"};\n')
        self.build = {
            'version': '1.8.3', 'name': 'main', 'module_id': 0,
            'ldscript': 'build/GC6E01/ldscript.lcf', 'entry': '_start',
            'units': [{'name': 'sound.c', 'object': 'originals/sound.o',
                       'autogenerated': False}],
            'modules': [], 'links': [],
        }

    def object(self, completed=True, **options):
        options.setdefault('mw_version', 'ProDG/3.5')
        return Object(completed, 'sound.c', cflags=[], **options).resolve(self.config, {})

    def generate(self, obj):
        generate_build_ninja(self.config, {obj.name: obj}, self.build)
        generate_objdiff_config(self.config, {obj.name: obj}, self.build)
        ninja = re.sub(r'\$\n\s*', '', Path('build.ninja').read_text())
        return ninja, json.loads(Path('objdiff.json').read_text())['units'][0]

    def test_view_is_built_for_report_but_native_source_is_linked(self):
        obj = self.object(comparison_view='prodg_data')
        ninja, unit = self.generate(obj)
        self.assertEqual(unit['target_path'], 'originals/sound.o')
        self.assertEqual(unit['base_path'], 'build/GC6E01/compare/sound.o')
        self.assertEqual(unit['metadata']['source_path'], 'src/sound.c')
        self.assertTrue(unit['metadata']['complete'])
        edge = next(s for s in ninja.splitlines() if s.startswith('build build/GC6E01/main.elf:'))
        self.assertIn('build/GC6E01/src/sound.o', edge)
        self.assertNotIn('/compare/', edge)
        source_edge = next(s for s in ninja.splitlines() if s.startswith('build all_source:'))
        self.assertIn('build/GC6E01/compare/sound.o', source_edge)
        self.assertIn('compare_prodg_data build/GC6E01/src/sound.o originals/sound.o', ninja)

    def test_view_cannot_grant_link_credit_to_a_candidate(self):
        ninja, unit = self.generate(self.object(False, comparison_view='prodg_data'))
        self.assertFalse(unit['metadata']['complete'])
        edge = next(s for s in ninja.splitlines() if s.startswith('build build/GC6E01/main.elf:'))
        self.assertIn('originals/sound.o', edge)
        self.assertNotIn('/compare/', edge)

    def test_data_names_view_changes_only_the_comparison_path(self):
        obj = self.object(comparison_view='data_names', mw_version='GC/1.2.5n',
                          symbol_mappings={'target_literal': '@12'})
        ninja, unit = self.generate(obj)
        self.assertEqual(unit['base_path'], 'build/GC6E01/compare/sound.o')
        self.assertEqual(unit['target_path'], 'originals/sound.o')
        self.assertNotIn('symbol_mappings', unit)
        self.assertEqual(json.loads(Path('build/GC6E01/compare/sound.names.json').read_text()),
                         {'target_literal': '@12'})
        edge = next(s for s in ninja.splitlines() if s.startswith('build build/GC6E01/main.elf:'))
        self.assertIn('build/GC6E01/src/sound.o', edge)
        self.assertNotIn('/compare/', edge)
        self.assertIn('compare_data_names build/GC6E01/src/sound.o originals/sound.o', ninja)

    def test_link_alignment_keeps_native_source_as_comparison_input(self):
        obj = self.object(data_alignment=4, mw_version='GC/1.2.5n')
        ninja, unit = self.generate(obj)
        self.assertEqual(unit['base_path'], 'build/GC6E01/src/sound.o')
        self.assertEqual(unit['target_path'], 'originals/sound.o')
        edge = next(s for s in ninja.splitlines() if s.startswith('build build/GC6E01/main.elf:'))
        self.assertIn('build/GC6E01/link/sound.o', edge)
        self.assertNotIn('originals/sound.o', edge)
        self.assertIn('link_data_alignment build/GC6E01/src/sound.o originals/sound.o', ninja)

    def test_link_alignment_cannot_promote_candidates_or_use_unknown_options(self):
        for completed, options in (
            (False, {'data_alignment': 4, 'mw_version': 'GC/1.2.5n'}),
            (True, {'data_alignment': 4, 'mw_version': 'ProDG/3.5'}),
            (True, {'data_alignment': 2, 'mw_version': 'GC/1.2.5n'}),
            (True, {'comparison_view': 'data_names'}),
        ):
            with self.subTest(options=options), self.assertRaises(SystemExit):
                self.object(completed, **options)

    def test_unknown_view_and_wrong_compiler_are_rejected(self):
        for options in ({'comparison_view': 'unknown'},
                        {'comparison_view': 'prodg_data', 'mw_version': 'GC/1.2.5n'}):
            with self.subTest(options=options), self.assertRaises(SystemExit):
                self.object(**options)

    def test_declared_symbol_mapping_is_reproducible_and_overrides_local_cache(self):
        Path('objdiff.json').write_text(json.dumps({'units': [
            {'name': 'main/sound', 'symbol_mappings': {'stale': 'local'}}]}))
        _, unit = self.generate(self.object(symbol_mappings={'target_table': 'source_table'}))
        self.assertEqual(unit['symbol_mappings'], {'target_table': 'source_table'})
        Path('objdiff.json').unlink()
        _, clean = self.generate(self.object(symbol_mappings={'target_table': 'source_table'}))
        self.assertEqual(clean, unit)

    def test_ambiguous_or_invalid_mapping_is_rejected(self):
        for mappings in ({'a': 'x', 'b': 'x'}, {'a': ''}, ['a'], {1: 'b'}):
            with self.subTest(mappings=mappings), self.assertRaises(SystemExit):
                self.object(symbol_mappings=mappings)


if __name__ == '__main__':
    unittest.main()
